                print(url, file=sys.stderr)
            req = urllib.request.Request(url, headers={'User-Agent': args.user_agent or 'Firefox'})
            with urllib.request.urlopen(req, timeout=args.timeout) as resp:
                return resp.read(), url
    except Exception as e:
        if not args.quiet:
            print(f"{url} (error sending request for url ({url}))", file=sys.stderr)
        return b"", url

