        if not attrs: return ""
        res = []
        for k, v in attrs:
            if v is None:
                res.append(k)
            else:
                # Need to escape quotes
                v = v.replace('"', '&quot;')
                res.append(f'{k}="{v}"')
        return " " + " ".join(res)

    def handle_starttag(self, tag, attrs):
        attr_dict = dict(attrs)

        # inject head meta
        if tag == "head":
            self.in_head = True
            self.head_injected = True
            self.output.append(f"<{tag}{self.make_attrs(attrs)}><meta name=\"robots\" content=\"none\"></meta>")
            return
        if tag == "body" and not self.head_injected:
            self.output.append(f"<head><meta name=\"robots\" content=\"none\"></meta></head>")
            self.head_injected = True

        if tag == "link" and attr_dict.get("rel") == "stylesheet" and "href" in attr_dict and not self.args.no_css:
            href = attr_dict["href"]
            url = urllib.parse.urljoin(self.base_url, href)
            data, _ = fetch_url(url, self.args)
            if data:
                b64 = base64.b64encode(data).decode('ascii')
                attr_dict["href"] = f"data:text/css;base64,{b64}"
            else:
                attr_dict["href"] = ""
            # Reconstruct attrs
            self.output.append(f"<{tag}{self.make_attrs(list(attr_dict.items()))}>")
            return

        if tag == "img" and "src" in attr_dict and not self.args.no_images:
            src = attr_dict["src"]
            url = urllib.parse.urljoin(self.base_url, src)
            data, _ = fetch_url(url, self.args)
            if data:
                ctype, _ = mimetypes.guess_type(url)
                ctype = ctype or "image/png"
                b64 = base64.b64encode(data).decode('ascii')
                attr_dict["src"] = f"data:{ctype};base64,{b64}"
            else:
                attr_dict["src"] = ""
            self.output.append(f"<{tag}{self.make_attrs(list(attr_dict.items()))}>")
            return

        if tag == "script" and "src" in attr_dict and not self.args.no_js:
            src = attr_dict["src"]
            url = urllib.parse.urljoin(self.base_url, src)
            data, _ = fetch_url(url, self.args)
            del attr_dict["src"]
            self.output.append(f"<{tag}{self.make_attrs(list(attr_dict.items()))}>{data.decode('utf-8', 'ignore')}")
